<script setup lang="ts">
import { ref, computed } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import AppShell from '../../components/AppShell.vue'
import ResourceCard from '../../components/ResourceCard.vue'
import Formula from '../../components/Formula.vue'
import Icon from '../../components/Icon.vue'
import { resources, chapters, nodes, resourceTypeEyebrow, isExternalUrl } from '../../data/course'
import { progress, completeResource, toggleBookmark, navigate } from '../../store'
const type = ref('all'), chapter = ref(''), nodeFilter = ref(''), search = ref(''), selectedId = ref(''), slideIndex = ref(0), videoError = ref(false)
const activeResource = computed(() => resources.find(r => r.id === selectedId.value))
const filtered = computed(() => resources.filter(r => (type.value === 'all' || r.type === type.value) && (!chapter.value || r.chapterId === chapter.value) && (!nodeFilter.value || r.nodeIds.includes(nodeFilter.value)) && (!search.value || (r.title + r.description + r.nodeIds.map(id => nodes.find(n => n.id === id)?.title).join(' ')).includes(search.value))))
const activeSlide = computed(() => activeResource.value?.slides?.[slideIndex.value])
onLoad(options => { if (options?.resource) { selectedId.value = options.resource; if (resources.some(r => r.id === options.resource)) { progress.lastResource = options.resource; try { localStorage.setItem('thermolearn.progress.v1', JSON.stringify(progress)) } catch {} } } if (options?.node) nodeFilter.value = options.node })
function close() { selectedId.value = ''; slideIndex.value = 0; videoError.value = false }
function selectResource(id:string) { selectedId.value = id; slideIndex.value=0; videoError.value=false; progress.lastResource=id }
</script>
<template><AppShell active="resources" title="视频与课件"><div class="page-heading"><div><h1>让每一个概念，都有迹可循</h1><p>跟随视频与课件，从直观观察走向深入理解。</p></div><span class="tag"><Icon name="book" :size="13" />{{ resources.length }} 项学习资源</span></div>
  <section class="resource-intro"><div><span class="eyebrow">A DIFFERENT WAY TO UNDERSTAND</span><h2>抽象的原理，也可以生动起来。</h2><p>观看过程，阅读推导，回到知识点建立联系。</p></div><div class="resource-intro-stats"><span><strong>{{ resources.filter(r => r.type === 'pdf').length }}</strong>PDF 课件</span><i></i><span><strong>{{ resources.filter(r => r.type === 'external').length }}</strong>网课分集</span><Icon name="video" :size="48" /></div></section>
  <div class="resource-toolbar"><div class="tabs" role="tablist" aria-label="资源类型"><button role="tab" :aria-selected="type==='all'" :class="{active:type==='all'}" @click="type='all'">全部资源</button><button role="tab" :aria-selected="type==='video'" :class="{active:type==='video'}" @click="type='video'">视频短片</button><button role="tab" :aria-selected="type==='slides'" :class="{active:type==='slides'}" @click="type='slides'">文字课件</button><button role="tab" :aria-selected="type==='pdf'" :class="{active:type==='pdf'}" @click="type='pdf'">PDF 课件</button><button role="tab" :aria-selected="type==='external'" :class="{active:type==='external'}" @click="type='external'">网课资源</button></div><div class="filter-bar"><select v-model="chapter" aria-label="按章节筛选资源"><option value="">全部章节</option><option v-for="c in chapters" :key="c.id" :value="c.id">第{{ Number(c.number) }}章 · {{ c.shortTitle }}</option></select><div class="local-search"><Icon name="search" :size="15" /><input v-model="search" placeholder="搜索资源或知识点" aria-label="搜索资源" /></div></div></div>
  <div v-if="nodeFilter" class="active-resource-filter"><span>知识点：{{ nodes.find(n=>n.id===nodeFilter)?.title }}</span><button @click="nodeFilter=''" aria-label="清除知识点筛选"><Icon name="close" :size="13" /></button></div><div class="resource-results-title"><span>为你找到 <strong>{{ filtered.length }}</strong> 项学习资源</span><span>按课程内容编排</span></div>
  <div v-if="filtered.length" class="resource-grid all-resources"><ResourceCard v-for="resource in filtered" :key="resource.id" :resource="resource" /></div><div v-else class="empty-state panel"><span class="empty-icon"><Icon name="search" :size="27" /></span><h3>{{ type === 'external' ? '还没有已核实的网课资源' : '这里的资源正在生长' }}</h3><p v-if="type === 'external'">当前章节或关键词下暂无已核实网课分集，可以调整筛选条件继续查找。</p><p v-else>当前筛选条件下暂无资源。可以调整章节或关键词，继续探索已有内容。</p><button class="button secondary" @click="type='all';chapter='';search='';nodeFilter=''">查看全部资源</button></div>
  <div class="resource-note"><Icon name="bulb" :size="18" /><div><strong>以知识点为线索，持续丰富课程资源</strong><p>课程 PDF 覆盖第 0–12 章；网课按目录分集登记，覆盖第 0–12 章。演示短片无声。打开 PDF 或网课不会自动完成学习，请学完后手动标记。</p></div></div>
  <div v-if="activeResource" class="modal-backdrop" @click.self="close"><section class="modal resource-modal" role="dialog" aria-modal="true" aria-labelledby="resource-dialog-title"><button class="modal-close icon-button" aria-label="关闭资源预览" @click="close"><Icon name="close" /></button><div class="resource-modal-heading"><span class="eyebrow">{{ resourceTypeEyebrow[activeResource.type] }}</span><h2 id="resource-dialog-title">{{ activeResource.title }}</h2><p v-if="activeResource.type === 'video'">自制教学演示 · 无声短片 · 16 秒</p><p v-else-if="activeResource.type === 'slides'">自制教学演示课件 · 4 页</p><p v-else-if="activeResource.type === 'pdf'">课程 PDF · {{ activeResource.source }}</p><p v-else>来源平台：{{ activeResource.source || '待补充' }}<template v-if="activeResource.author"> · 主讲/作者：{{ activeResource.author }}</template></p></div><div v-if="activeResource.type==='video'" class="video-container"><video v-if="!videoError" :key="activeResource.id" :src="activeResource.src" :poster="'/static/media/'+activeResource.theme+'-cover.png'" controls playsinline preload="metadata" @error="videoError=true" @ended="completeResource(activeResource.id)" aria-label="教学演示视频"></video><div v-else class="video-error"><Icon name="video" :size="30" /><p>视频暂时无法加载，请检查本地媒体文件。</p><button class="button" @click="videoError=false">重新加载</button></div></div><div v-else-if="activeResource.type === 'slides'" class="slide-reader"><div class="slide-sheet"><span class="slide-kicker">热知 / 工程热力学</span><span class="slide-number">{{ String(slideIndex+1).padStart(2,'0') }}</span><h3>{{ activeSlide?.title }}</h3><ul><li v-for="(line,index) in activeSlide?.body" :key="index">{{ line }}</li></ul><Formula :value="activeSlide?.formula" /><span class="slide-watermark">THERMO LEARN · KNOWLEDGE NOTES</span></div><div class="slide-controls"><button class="button small" :disabled="slideIndex===0" @click="slideIndex--">上一页</button><div class="slide-dots"><button v-for="(_,index) in activeResource.slides" :key="index" :class="{active:slideIndex===index}" :aria-label="'前往第'+(index+1)+'页'" @click="slideIndex=index"></button></div><span>{{ slideIndex+1 }} / {{ activeResource.slides?.length }}</span><button class="button small" :disabled="slideIndex===(activeResource.slides?.length || 1)-1" @click="slideIndex++">下一页</button></div></div><div v-else-if="activeResource.type === 'pdf'" class="external-panel"><div class="external-info"><span class="external-badge"><Icon name="file" :size="13" />课程 PDF</span><p>{{ activeResource.description }}</p></div><div class="external-actions"><a class="button primary external-link" :href="activeResource.src" target="_blank" rel="noopener noreferrer">打开 PDF<Icon name="arrow" :size="15" /></a><p class="external-hint">在新标签页使用浏览器阅读器查看。手机可能下载文件或使用外部阅读器。若打不开，请返回此页重试。阅读完成后请手动标记已学。</p></div></div><div v-else class="external-panel"><div class="external-info"><span class="external-badge"><Icon name="link" :size="13" />网课资源</span><h3>{{ activeResource.course || activeResource.title }}</h3><p v-if="activeResource.source || activeResource.author">来源平台：{{ activeResource.source || '待补充' }}<template v-if="activeResource.author"> · 主讲/作者：{{ activeResource.author }}</template></p><p v-if="activeResource.description" class="external-desc">{{ activeResource.description }}</p></div><div v-if="isExternalUrl(activeResource.url)" class="external-actions"><a class="button primary external-link" :href="activeResource.url" target="_blank" rel="noopener noreferrer">在新标签页打开课程<Icon name="arrow" :size="15" /></a><p class="external-hint">课程在外部平台播放，本站不镜像其内容。打开只会记录「已访问」，只有点「标记已学」才计入完成。</p></div><div v-else class="external-actions"><button class="button primary" disabled>链接待补充</button><p class="external-hint">该课程链接暂不可用，请选择其他资源。</p></div></div><div class="resource-modal-bottom"><div class="resource-connected"><span>{{ activeResource.nodeIds.length ? '关联知识点' : '本资源仅关联章节' }}</span><button v-for="id in activeResource.nodeIds" :key="id" class="chip" @click="navigate('graph',{node:id})">{{ nodes.find(n=>n.id===id)?.title }}<Icon name="arrow" :size="11" /></button></div><div class="resource-modal-actions"><button class="button" @click="toggleBookmark(activeResource.id)"><Icon name="bookmark" :size="16" />{{ progress.bookmarks.includes(activeResource.id)?'已收藏':'收藏资源' }}</button><button class="button primary" :disabled="progress.completed.includes(activeResource.id)" @click="completeResource(activeResource.id)"><Icon name="check" :size="17" />{{ progress.completed.includes(activeResource.id)?'已完成学习':'标记已学' }}</button><button v-if="activeResource.nodeIds.length" class="button secondary" @click="navigate('practice',{node:activeResource.nodeIds[0]})">练习巩固 <Icon name="arrow" :size="15" /></button></div><p class="completion-hint">完成状态保存至当前浏览器；已学知识点依据资源完成标记统计，不代表掌握程度。</p></div></section></div>
</AppShell></template>
<style scoped>
